using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Windows.Forms;
namespace IDSketcher{
class BrightnessSlider:Control{
 int current=50;public int Minimum{get{return 0;}set{}}public int Maximum{get{return 100;}set{}}public TickStyle TickStyle{get;set;}public event EventHandler ValueChanged;public Color MidColour=Color.Gray;
 public BrightnessSlider(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.Selectable,true);TabStop=true;AccessibleName="Brightness";}
 public int Value{get{return current;}set{int next=Math.Max(0,Math.Min(100,value));if(next==current)return;current=next;Invalidate();if(ValueChanged!=null)ValueChanged(this,EventArgs.Empty);}}
 public Color ColourAt(int percent){float t=Math.Max(0,Math.Min(100,percent))/50f;return t<=1?Color.FromArgb((int)Math.Round(MidColour.R*t),(int)Math.Round(MidColour.G*t),(int)Math.Round(MidColour.B*t)):Color.FromArgb((int)Math.Round(MidColour.R+(255-MidColour.R)*(t-1)),(int)Math.Round(MidColour.G+(255-MidColour.G)*(t-1)),(int)Math.Round(MidColour.B+(255-MidColour.B)*(t-1)));}
 public void SetColor(Color colour){double hi=Math.Max(colour.R,Math.Max(colour.G,colour.B))/255.0,lo=Math.Min(colour.R,Math.Min(colour.G,colour.B))/255.0,light=(hi+lo)/2,den=1-Math.Abs(2*light-1);if(den>.00001){double saturation=(hi-lo)/den;var pure=Wheel.Hsv(colour.GetHue(),1,1);double min=(1-saturation)*127.5;MidColour=Color.FromArgb((int)Math.Round(min+pure.R*saturation),(int)Math.Round(min+pure.G*saturation),(int)Math.Round(min+pure.B*saturation));}Value=(int)Math.Round(light*100);Invalidate();}
 Rectangle Track{get{int edge=Math.Max(5,(int)(5*SharpDpi.Factor(this)));return new Rectangle(edge,Height/2-Math.Max(3,Height/6),Math.Max(1,Width-edge*2),Math.Max(6,Height/3));}}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var r=Track;using(var fill=new LinearGradientBrush(r,Color.Black,Color.White,0f)){fill.InterpolationColors=new ColorBlend{Colors=new[]{Color.Black,MidColour,Color.White},Positions=new[]{0f,.5f,1f}};e.Graphics.FillRectangle(fill,r);}e.Graphics.DrawRectangle(Pens.Gray,r);float x=r.Left+r.Width*Value/100f;using(var pen=new Pen(Theme.Accent,Math.Max(2,2*SharpDpi.Factor(this))))e.Graphics.DrawLine(pen,x,r.Top-4,x,r.Bottom+4);if(Focused)ControlPaint.DrawFocusRectangle(e.Graphics,ClientRectangle);}
 void Pick(int x){var r=Track;Value=(int)Math.Round((x-r.Left)*100.0/r.Width);}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;Focus();Capture=true;Pick(e.X);}protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(Capture)Pick(e.X);}protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);Capture=false;}
 protected override bool IsInputKey(Keys key){return key==Keys.Left||key==Keys.Right||key==Keys.Home||key==Keys.End||base.IsInputKey(key);}protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Left)Value--;else if(e.KeyCode==Keys.Right)Value++;else if(e.KeyCode==Keys.Home)Value=0;else if(e.KeyCode==Keys.End)Value=100;else{base.OnKeyDown(e);return;}e.Handled=true;}
}
