partial class Canvas{
 public void TestAxisPointDragging(){
  Doc.Selected.Vectors.Clear();Doc.Selected.InvalidateVectors();CancelVector();VectorMode="Line";TestDrag(new Point(50,60),new Point(250,60));VectorMode="Select/edit";testAxisShift=true;try{PickVector(new PointF(50,60),Keys.None);VectorMove(new PointF(110,80));VectorMove(new PointF(120,200));VectorUp(new PointF(120,200));if(selectedVector.Points[0]!=new PointF(120,60))throw new Exception("Shift horizontal point axis stays locked");PickVector(new PointF(120,60),Keys.None);VectorMove(new PointF(130,150));VectorUp(new PointF(200,180));if(selectedVector.Points[0]!=new PointF(120,180))throw new Exception("Shift vertical point axis stays locked");testAxisShift=false;PickVector(new PointF(120,180),Keys.None);VectorMove(new PointF(160,210));VectorUp(new PointF(160,210));if(selectedVector.Points[0]!=new PointF(160,210))throw new Exception("Point free drag without Shift");}finally{testAxisShift=null;}
 }
 PointF pointDragOrigin;int pointDragAxis;bool? testAxisShift;
 void BeginPointAxis(){pointDragAxis=0;if(selectedVector!=null&&vectorHandle>=0)pointDragOrigin=selectedVector.Grips()[vectorHandle];}
 PointF ConstrainPointAxis(PointF p){if(selectedVector==null||vectorHandle<0||draft!=null)return p;if(!(testAxisShift??((ModifierKeys&Keys.Shift)!=0))){pointDragAxis=0;return p;}float dx=p.X-pointDragOrigin.X,dy=p.Y-pointDragOrigin.Y;if(pointDragAxis==0&&Math.Max(Math.Abs(dx),Math.Abs(dy))>.01f)pointDragAxis=Math.Abs(dx)>=Math.Abs(dy)?1:2;return pointDragAxis==1?new PointF(p.X,pointDragOrigin.Y):pointDragAxis==2?new PointF(pointDragOrigin.X,p.Y):pointDragOrigin;}
}
